**`src/CheckoutScreen.tsx`**
```tsx
import React, { useEffect, useMemo, useRef, useState } from 'react';
import './CheckoutScreen.css';
import { CartItem, DeliveryAddress, emptyAddress } from './types';

interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string;
  deliveryFee?: number;
  onBack: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
}

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

function formatMoney(amount: number, currency: string): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 2,
  }).format(amount);
}

function validate(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Full name is required';
  }

  const digits = address.phone.replace(/\D/g, '');
  if (!digits) {
    errors.phone = 'Phone number is required';
  } else if (digits.length < 7) {
    errors.phone = 'Enter a valid phone number';
  }

  if (!address.city.trim()) {
    errors.city = 'City is required';
  }

  if (!address.street.trim()) {
    errors.street = 'Street and house number are required';
  }

  return errors;
}

const CheckoutScreen: React.FC<CheckoutScreenProps> = ({
  items,
  currency = 'USD',
  deliveryFee = 4.99,
  onBack,
  onPay,
}) => {
  const [address, setAddress] = useState<DeliveryAddress>(emptyAddress);
  const [errors, setErrors] = useState<FormErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const tg = typeof window !== 'undefined' ? window.Telegram?.WebApp : undefined;
  const payHandlerRef = useRef<() => void>(() => {});

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + (items.length > 0 ? deliveryFee : 0);

  const isValid = useMemo(() => Object.keys(validate(address)).length === 0, [address]);

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const value = e.target.value;
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validate({ ...address }));
  };

  const submit = async () => {
    const validationErrors = validate(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      apartment: true,
      comment: true,
    });

    if (Object.keys(validationErrors).length > 0) {
      tg?.HapticFeedback.notificationOccurred('error');
      setSubmitError('Please fix the highlighted fields.');
      return;
    }

    setSubmitError(null);
    setSubmitting(true);
    tg?.MainButton.showProgress(true);
    try {
      await onPay(address);
      tg?.HapticFeedback.notificationOccurred('success');
    } catch (err) {
      tg?.HapticFeedback.notificationOccurred('error');
      setSubmitError(err instanceof Error ? err.message : 'Payment failed. Please try again.');
    } finally {
      setSubmitting(false);
      tg?.MainButton.hideProgress();
    }
  };

  payHandlerRef.current = submit;

  useEffect(() => {
    if (!tg) return;

    const mainButton = tg.MainButton;
    const onClick = () => payHandlerRef.current();

    mainButton.setText(`Pay ${formatMoney(total, currency)}`);
    isValid && items.length > 0 ? mainButton.enable() : mainButton.disable();
    mainButton.show();
    mainButton.onClick(onClick);

    return () => {
      mainButton.offClick(onClick);
      mainButton.hide();
    };
  }, [tg, total, currency, isValid, items.length]);

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout-screen">
      <header className="checkout-header">
        <button
          type="button"
          className="back-button"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <span className="back-icon" aria-hidden="true">
            ‹
          </span>
          Back
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </header>

      <section className="cart-summary">
        <h2 className="section-title">Order</h2>
        {items.length === 0 ? (
          <p className="empty-cart">Your cart is empty.</p>
        ) : (
          <ul className="cart-list">
            {items.map((item) => (
              <li key={item.id} className="cart-item">
                <div className="cart-item-thumb">
                  {item.imageUrl ? (
                    <img src={item.imageUrl} alt={item.name} />
                  ) : (
                    <div className="cart-item-thumb-placeholder" aria-hidden="true" />
                  )}
                </div>
                <div className="cart-item-info">
                  <span className="cart-item-name">{item.name}</span>
                  <span className="cart-item-qty">Qty {item.quantity}</span>
                </div>
                <span className="cart-item-price">
                  {formatMoney(item.price * item.quantity, currency)}
                </span>
              </li>
            ))}
          </ul>
        )}

        <div className="summary-row">
          <span>Subtotal</span>
          <span>{formatMoney(subtotal, currency)}</span>
        </div>
        <div className="summary-row">
          <span>Delivery</span>
          <span>{items.length > 0 ? formatMoney(deliveryFee, currency) : formatMoney(0, currency)}</span>
        </div>
        <div className="summary-row summary-total">
          <span>Total</span>
          <span>{formatMoney(total, currency)}</span>
        </div>
      </section>

      <section className="address-form">
        <h2 className="section-title">Delivery address</h2>

        <div className="form-field">
          <label htmlFor="fullName">Full name</label>
          <input
            id="fullName"
            type="text"
            autoComplete="name"
            value={address.fullName}
            onChange={handleChange('fullName')}
            onBlur={handleBlur('fullName')}
            className={fieldError('fullName') ? 'input-error' : ''}
          />
          {fieldError('fullName') && <span className="error-text">{fieldError('fullName')}</span>}
        </div>

        <div className="form-field">
          <label htmlFor="phone">Phone number</label>
          <input
            id="phone"
            type="tel"
            autoComplete="tel"
            placeholder="+1 555 123 4567"
            value={address.phone}
            onChange={handleChange('phone')}
            onBlur={handleBlur('phone')}
            className={fieldError('phone') ? 'input-error' : ''}
          />
          {fieldError('phone') && <span className="error-text">{fieldError('phone')}</span>}
        </div>

        <div className="form-field">
          <label htmlFor="city">City</label>
          <input
            id="city"
            type="text"
            autoComplete="address-level2"
            value={address.city}
            onChange={handleChange('city')}
            onBlur={handleBlur('city')}
            className={fieldError('city') ? 'input-error' : ''}
          />
          {fieldError('city') && <span className="error-text">{fieldError('city')}</span>}
        </div>

        <div className="form-row">
          <div className="form-field form-field-grow">
            <label htmlFor="street">Street and house number</label>
            <input
              id="street"
              type="text"
              autoComplete="street-address"
              value={address.street}
              onChange={handleChange('street')}
              onBlur={handleBlur('street')}
              className={fieldError('street') ? 'input-error' : ''}
            />
            {fieldError('street') && <span className="error-text">{fieldError('street')}</span>}
          </div>

          <div className="form-field form-field-small">
            <label htmlFor="apartment">Apt / suite</label>
            <input
              id="apartment"
              type="text"
              value={address.apartment}
              onChange={handleChange('apartment')}
              onBlur={handleBlur('apartment')}
            />
          </div>
        </div>

        <div className="form-field">
          <label htmlFor="comment">Comment for courier (optional)</label>
          <textarea
            id="comment"
            rows={3}
            value={address.comment}
            onChange={handleChange('comment')}
            onBlur={handleBlur('comment')}
          />
        </div>
      </section>

      {submitError && <p className="submit-error">{submitError}</p>}

      {!tg && (
        <button
          type="button"
          className="pay-button"
          disabled={!isValid || items.length === 0 || submitting}
          onClick={submit}
        >
          {submitting ? 'Processing…' : `Pay ${formatMoney(total, currency)}`}
        </button>
      )}
    </div>
  );
};

export default CheckoutScreen;
```

